package com.example.events.service;
import com.example.events.Event;import com.example.events.repository.EventRepository;import org.junit.jupiter.api.Test;import java.time.LocalDateTime;import java.util.List;import static org.junit.jupiter.api.Assertions.*;import java.lang.reflect.Proxy;
class EventServiceTest {
 @Test void upcomingFiltersSearchAndCategoryAndExcludesPastEvents(){@SuppressWarnings("unchecked") EventRepository repo=(EventRepository)Proxy.newProxyInstance(EventRepository.class.getClassLoader(),new Class[]{EventRepository.class},(proxy,method,args)->method.getName().equals("findByStatusOrderByDateTimeAsc")?List.of():null);Event first=new Event();first.title="Community Design Jam";first.description="Meet makers";first.category="Community";first.venue="Studio";first.dateTime=LocalDateTime.now().plusDays(3);Event second=new Event();second.title="Future Jazz Night";second.description="Live music";second.category="Music";second.venue="Hall";second.dateTime=LocalDateTime.now().plusDays(5);Event past=new Event();past.title="Past Community meetup";past.category="Community";past.dateTime=LocalDateTime.now().minusDays(1);List<Event> all=List.of(first,second,past);EventRepository wrapped=(EventRepository)Proxy.newProxyInstance(EventRepository.class.getClassLoader(),new Class[]{EventRepository.class},(proxy,method,args)->method.getName().equals("findByStatusOrderByDateTimeAsc")?all:null);EventService service=new EventService(wrapped);assertEquals(List.of(first),service.upcoming("design","community"));assertTrue(service.upcoming("missing","").isEmpty());}
}

